// [실제 속성 이름과 동일한 독립 축 / Independent axes using actual prop names]
const enumAxis = <Enum extends string>() => <const Values extends readonly Enum[]>(values: Values & ([Enum] extends [Values[number]] ? unknown : never)) => values;

const liveContracts: Readonly<Record<string, { axes: ComponentAxes; states: readonly string[] }>> = {
    text: { axes: { variant: Object.keys(TEXT_VARIANTS), size: Object.keys(TEXT_SIZES) }, states: [] },
    icon: { axes: { group: enumAxis<NonNullable<ComponentProps<typeof Icon>["group"]>>()([...ICON_GROUPS]) }, states: [] },
    surface: { axes: { variant: SURFACE_VARIANTS, padding: SURFACE_PADDINGS, radius: SURFACE_RADII }, states: [] },
    button: { axes: { variant: CONTROL_VARIANTS, context: CONTROL_CONTEXTS, shape: CONTROL_SHAPES }, states: ["default", "disabled", "pressed"] },
    "button-link": { axes: { variant: CONTROL_VARIANTS, context: CONTROL_CONTEXTS, shape: CONTROL_SHAPES }, states: [] },
    "icon-button": { axes: { variant: CONTROL_VARIANTS, context: CONTROL_CONTEXTS, shape: CONTROL_SHAPES }, states: ["disabled", "pressed"] },
    "filter-button": { axes: { variant: CONTROL_VARIANTS, context: CONTROL_CONTEXTS, shape: CONTROL_SHAPES, selected: ["false", "true"] }, states: ["disabled"] },
    field: { axes: { as: enumAxis<NonNullable<SystemFieldProps["as"]>>()([...FIELD_ELEMENTS]), variant: CONTROL_CONTEXTS }, states: ["default", "disabled", "error", "required", "readonly"] },
    checkbox: { axes: {}, states: ["unchecked", "checked", "disabled"] },
    badge: { axes: { tone: BADGE_TONES, appearance: APPEARANCES }, states: [] },
    notice: { axes: { variant: CONTROL_CONTEXTS }, states: ["status", "error"] },
    tabs: { axes: { orientation: TAB_ORIENTATIONS }, states: ["selected", "disabled"] },
    disclosure: { axes: { appearance: APPEARANCES }, states: ["closed", "open"] },
    "hero-slide": { axes: {
        layout: enumAxis<NonNullable<ComponentProps<typeof HeroSlide>["layout"]>>()([...HERO_SLIDE_LAYOUTS]),
        preview: enumAxis<NonNullable<ComponentProps<typeof HeroSlide>["preview"]>>()([...HERO_SLIDE_PREVIEWS]),
    }, states: ["active", "entering"] },
    "account-mini-room": { axes: { theme: enumAxis<ComponentProps<typeof AccountMiniRoom>["theme"]>()([...ROOM_THEMES]) }, states: ["light-on", "light-off"] },
    "account-membership": { axes: { mode: enumAxis<ComponentProps<typeof AccountMembershipCard>["mode"]>()([...MEMBERSHIP_MODES]) }, states: [] },
    "account-ticket": { axes: { variant: enumAxis<NonNullable<ComponentProps<typeof AccountTicket>["variant"]>>()([...TICKET_VARIANTS]) }, states: ["cancelled"] },
    glass: { axes: { variant: Object.keys(GLASS_MATERIALS) }, states: [] },
    "floating-panel": { axes: { variant: enumAxis<PanelVariant>()([...PANEL_PRESENTATIONS]) }, states: [] },
    header: { axes: { variant: enumAxis<NonNullable<ComponentProps<typeof Header>["variant"]>>()(["default", "inverse"]) }, states: [] },
};

export const COMPONENT_REGISTRY: readonly ComponentDefinition[] = definitions.map(record => {
    const contract = liveContracts[record.id];
    return contract ? { ...record, ...contract, examples: contractExamples(record.id, contract.axes, contract.states) } : record;
});

